    LANGUAGE_WRAPPER = 'Let vectors v_1, v_2, \\ldots, v_{n} in \\mathbb{R}^{[dimension]} satisfy\\n\\n\\sum_{k=1}^{[n]} v_k = 0, \\qquad \\sum_{k=1}^{[n]} \\|v_k\\|^2 = [sum_squares].\\n\\nDetermine the minimum possible value of\\n\\n\\max_{1 \\le i < j \\le [n]} \\|v_i - v_j\\|.\\n\\nAfter solving the above problem, please output your final answer in the following format:\\n### The final answer is: $\\boxed{<your answer>}$.\\nThe final answer should be given as precisely as possible (using LaTeX symbols such as \\sqrt, \\frac, \\pi, etc.). If the final answer involves a decimal approximation, it must be accurate to at least four decimal places.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We generate n = t*(d+1) to ensure an exact equality construction via a regular simplex repeated t times.
# We also choose sum_squares so that the final radical is not a perfect square (to avoid trivial answers).
import math
for _ in range(100):
    d = rng.randint(2, 7)
    t = rng.randint(3, 50)
    n = t * (d + 1)
    S = rng.randint(1, 200)
    # General formula for minimal diameter uses k = min(d, n-1) = d here (since n >= d+1).
    k = d
    rad_num = 2 * S * (k + 1)
    rad_den = n * k
    g = math.gcd(rad_num, rad_den)
    rad_num //= g
    rad_den //= g
    # Enforce non-triviality: the radicand should not be a rational perfect square.
    def is_perfect_square(x):
        r = int(math.isqrt(x))
        return r*r == x
    if not (is_perfect_square(rad_num) and is_perfect_square(rad_den)):
        # Additional mild difficulty: avoid exact 1 under the sqrt.
        if not (rad_num == rad_den):
            return {'n': n, 'dimension': d, 'sum_squares': S}
# Fallback if difficulty constraints fail repeatedly.
d = 3
t = 7
n = t * (d + 1)
S = 97
return {'n': n, 'dimension': d, 'sum_squares': S}

    def verifier(assign):
# Validate and compute the exact minimal maximal pairwise distance using Jung's theorem.
# The minimum is achieved by a regular simplex construction with repeats when n is a multiple of (dimension+1).
import math
# Basic validation
if not isinstance(assign, dict):
    return (False, None)  # invalid structure
n = assign.get('n')
d = assign.get('dimension')
S = assign.get('sum_squares')
if not (isinstance(n, int) and isinstance(d, int) and isinstance(S, int)):
    return (False, None)  # invalid types
if n < 3 or d < 2 or S <= 0:
    return (False, None)  # domain constraints
# Enforce equality-construction feasibility and difficulty: n must be multiple of (d+1)
if n % (d + 1) != 0:
    return (False, None)  # we require this to ensure the extremal configuration exists exactly
# Compute k = min(d, n-1). Given n >= d+1, k = d.
k = min(d, n - 1)
# Minimal diameter formula:
# D_min = sqrt( 2 * S * (k+1) / (n * k) ), achieved by placing points at vertices of a regular k-simplex
# scaled so each has norm sqrt(S/n), repeated evenly when n > k+1.
rad_num = 2 * S * (k + 1)
rad_den = n * k
# Reduce fraction under the radical for clean output
g = math.gcd(rad_num, rad_den)
rad_num //= g
rad_den //= g
# Difficulty enforcement: avoid trivial perfect-square rational
def is_perfect_square(x):
    r = int(math.isqrt(x))
    return r*r == x
if is_perfect_square(rad_num) and is_perfect_square(rad_den):
    return (False, None)  # too trivial; generator is supposed to avoid this
if rad_den == 1:
    ans_expr = f"### The final answer is: $\\boxed{{\\sqrt{{{rad_num}}}}}$"
else:
    ans_expr = f"### The final answer is: $\\boxed{{\\sqrt{{\\frac{{{rad_num}}}{{{rad_den}}}}}}}$"
return (True, ans_expr)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")
